// Draw spiral with cool tones
function drawSpiral(ctx, x, y, size, depth) {
    if (depth > 0) {
        // Calculate next point in spiral
        const angle = depth * 0.3;
        const dx = Math.cos(angle) * size;
        const dy = Math.sin(angle) * size;

        // Draw segment
        ctx.fillStyle = `hsl(${20 + depth * 10}, 70%, ${50 + depth * 10}%)`;
        ctx.fillRect(x, y, 1, 1);

        // Recursive call for next segment
        drawSpiral(ctx, x + dx, y + dy, size * 0.75, depth - 1);
    }
}

